-- =================================================================
-- ARSITEKTUR PROFESIONAL FINAL - RETRIBUSI PELAYANAN KESEHATAN
-- Perda Kota Surabaya No. 7 Tahun 2023 (Perubahan)
-- Perubahan dari versi sebelumnya:
--   1. master_kategori  : tambah parent_id (hierarki 2 level)
--   2. master_komponen  : hapus kolom harga
--   3. master_peraturan : tabel baru (riwayat regulasi)
--   4. tarif_retribusi  : rename + tambah peraturan_id/kategori_id/
--                         harga/tanggal_mulai/tanggal_akhir/status
--                         TANPA rekening_id (diambil via faskes)
-- =================================================================

DROP VIEW IF EXISTS v_tarif_lengkap CASCADE;
DROP VIEW IF EXISTS v_master_komponen CASCADE;
DROP TABLE IF EXISTS tarif_retribusi CASCADE;
DROP TABLE IF EXISTS tabel_retribusi CASCADE;
DROP TABLE IF EXISTS master_komponen CASCADE;
DROP TABLE IF EXISTS master_kategori CASCADE;
DROP TABLE IF EXISTS master_peraturan CASCADE;
DROP TABLE IF EXISTS master_user CASCADE;
DROP TABLE IF EXISTS master_role CASCADE;
DROP TABLE IF EXISTS master_skpd CASCADE;
DROP TABLE IF EXISTS master_faskes CASCADE;
DROP TABLE IF EXISTS master_rekening CASCADE;

-- 1. MASTER REKENING
CREATE TABLE master_rekening (
    id            SERIAL      PRIMARY KEY,
    kode_rekening VARCHAR(50) UNIQUE NOT NULL,
    nama_rekening VARCHAR(255) NOT NULL
);

-- 2. MASTER FASKES (menyimpan rekening_id — relasi 1:N ke rekening)
CREATE TABLE master_faskes (
    id          SERIAL      PRIMARY KEY,
    kode_faskes VARCHAR(20) UNIQUE NOT NULL,
    nama_faskes VARCHAR(255) NOT NULL,
    rekening_id INT NOT NULL REFERENCES master_rekening(id)
);

-- 3. MASTER PERATURAN (riwayat regulasi — Perda, Perkada, dll)
CREATE TABLE master_peraturan (
    id               SERIAL      PRIMARY KEY,
    jenis_peraturan  VARCHAR(50) NOT NULL,           -- Perda / Perkada / SK
    nomor            VARCHAR(20) NOT NULL,
    tahun            SMALLINT    NOT NULL,
    tentang          TEXT        NOT NULL,
    tanggal_berlaku  DATE        NOT NULL,
    status           VARCHAR(20) NOT NULL DEFAULT 'aktif'
                     CHECK (status IN ('aktif','tidak aktif','dicabut'))
);

-- 4. MASTER KATEGORI (hierarki 2 level via parent_id self-referencing)
CREATE TABLE master_kategori (
    id            SERIAL       PRIMARY KEY,
    nama_kategori VARCHAR(255) NOT NULL,
    parent_id     INT          REFERENCES master_kategori(id) ON DELETE SET NULL
);
CREATE INDEX idx_kategori_parent ON master_kategori(parent_id);

-- 5. MASTER KOMPONEN (nama layanan + satuan — harga ada di tarif_retribusi)
CREATE TABLE master_komponen (
    id            SERIAL       PRIMARY KEY,
    kategori_id   INT          NOT NULL REFERENCES master_kategori(id) ON DELETE CASCADE,
    nama_komponen TEXT         NOT NULL,
    satuan        VARCHAR(100)
);
CREATE INDEX idx_komponen_kategori ON master_komponen(kategori_id);
CREATE INDEX idx_komponen_nama     ON master_komponen(nama_komponen);

-- 6. TARIF RETRIBUSI
--    faskes_id  → rekening diperoleh melalui master_faskes.rekening_id
--    kategori_id disimpan langsung agar filter per kategori cepat
--    tanggal_mulai/akhir + status memungkinkan riwayat tarif antar Perda
CREATE TABLE tarif_retribusi (
    id              SERIAL      PRIMARY KEY,
    peraturan_id    INT         NOT NULL REFERENCES master_peraturan(id) ON DELETE CASCADE,
    faskes_id       INT         NOT NULL REFERENCES master_faskes(id)    ON DELETE CASCADE,
    kategori_id     INT         NOT NULL REFERENCES master_kategori(id)  ON DELETE CASCADE,
    komponen_id     INT         NOT NULL REFERENCES master_komponen(id)  ON DELETE CASCADE,
    harga           BIGINT      NOT NULL,
    tanggal_mulai   DATE        NOT NULL DEFAULT CURRENT_DATE,
    tanggal_akhir   DATE,
    status          VARCHAR(20) NOT NULL DEFAULT 'aktif'
                    CHECK (status IN ('aktif','tidak aktif'))
);
CREATE INDEX idx_tarif_peraturan ON tarif_retribusi(peraturan_id);
CREATE INDEX idx_tarif_faskes    ON tarif_retribusi(faskes_id);
CREATE INDEX idx_tarif_kategori  ON tarif_retribusi(kategori_id);
CREATE INDEX idx_tarif_komponen  ON tarif_retribusi(komponen_id);
CREATE INDEX idx_tarif_status    ON tarif_retribusi(status);

-- VIEW: Komponen + Kategori (dengan hierarki parent)
CREATE OR REPLACE VIEW v_master_komponen AS
SELECT
    komp.id                AS komponen_id,
    kat.id                 AS kategori_id,
    kat.nama_kategori,
    parent.nama_kategori   AS parent_kategori,
    komp.nama_komponen,
    komp.satuan
FROM master_komponen komp
JOIN master_kategori kat    ON komp.kategori_id = kat.id
LEFT JOIN master_kategori parent ON kat.parent_id = parent.id;

-- VIEW: Tarif Lengkap (all-in-one untuk laporan & analisis)
CREATE OR REPLACE VIEW v_tarif_lengkap AS
SELECT
    t.id               AS tarif_id,
    t.peraturan_id,
    per.jenis_peraturan,
    per.nomor          AS no_peraturan,
    per.tahun,
    per.status         AS peraturan_status,
    t.faskes_id,
    f.kode_faskes,
    f.nama_faskes,
    rek.kode_rekening,
    rek.nama_rekening,
    t.kategori_id,
    parent.nama_kategori AS kelompok_kategori,
    kat.nama_kategori,
    t.komponen_id,
    komp.nama_komponen,
    komp.satuan,
    t.harga,
    t.tanggal_mulai,
    t.tanggal_akhir,
    t.status
FROM tarif_retribusi t
JOIN master_peraturan per  ON t.peraturan_id = per.id
JOIN master_faskes    f    ON t.faskes_id    = f.id
JOIN master_rekening  rek  ON f.rekening_id  = rek.id
JOIN master_kategori  kat  ON t.kategori_id  = kat.id
LEFT JOIN master_kategori parent ON kat.parent_id = parent.id
JOIN master_komponen  komp ON t.komponen_id  = komp.id;

BEGIN;







COMMIT;
